ms:center;background:#fff;border:1px solid var(--line);padding:14px;border-radius:18px;box-shadow:0 7px 22px rgba(55,31,46,.06)}.no{width:42px;height:42px;border-radius:14px;background:#fbf5e7;color:var(--wine2);display:grid;place-items:center;font-weight:950}.step b{display:block;font-size:14px;margin-bottom:3px}.step span{color:var(--muted);font-size:13px;line-height:1.45}.notice{margin-top:20px;padding:14px 16px;border-radius:16px;background:#e8f4ed;color:var(--ok);font-size:13px;line-height:1.5;font-weight:700}.pageActions{position:fixed;top:max(12px,env(safe-area-inset-top));right:max(12px,env(safe-area-inset-right));z-index:50;display:flex;gap:8px}.pageAction{border:1px solid rgba(255,255,255,.38);background:rgba(35,18,29,.82);backdrop-filter:blur(12px);color:#fff;border-radius:13px;min-height:44px;padding:0 14px;display:inline-flex;align-items:center;justify-content:center;gap:7px;font-weight:850;cursor:pointer;box-shadow:0 10px 26px rgba(20,7,15,.24)}.pageAction.closeOnly{width:44px;padding:0;font-size:18px}.pageAction:hover{background:#24151f}@media(max-width:760px){body{padding:72px 10px 10px}.shell{grid-template-columns:1fr;border-radius:23px}.hero{padding:30px 25px}.hero h1{margin:34px 0 14px;font-size:38px}.panel{padding:30px 22px}.hero:after{display:none}.pageActions{left:max(10px,env(safe-area-inset-left));right:max(10px,env(safe-area-inset-right));justify-content:space-between}.pageAction:first-child{flex:1}.pageAction.closeOnly{flex:0 0 44px}}
