.customerTop{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}.customerActions{display:flex;gap:6px;flex-wrap:wrap;margin-top:13px}.customerAction{border:0;border-radius:11px;padding:8px 10px;background:var(--soft);color:var(--wine);font-size:11px;font-weight:900;cursor:pointer;text-decoration:none}.customerAction:hover{background:#f1e6d7}.customerAction.delete{margin-left:auto;background:#fff0ef;color:var(--danger)}
@media(max-width:980px){.layout{grid-template-columns:1fr}.side{display:none}.customerGrid{grid-template-columns:repeat(2,1fr)}.reservation{grid-template-columns:1fr 130px 130px}.hallCol{display:none}.amountCol{text-align:right}.actions{grid-column:1/-1;justify-content:flex-start}.mobileNav{position:fixed;display:grid;grid-template-columns:repeat(4,1fr);left:10px;right:10px;bottom:max(10px,env(safe-area-inset-bottom));z-index:40;background:rgba(255,255,255,.96);border:1px solid var(--line);border-radius:19px;padding:7px;box-shadow:0 16px 45px rgba(59,32,50,.2);backdrop-filter:blur(12px)}.mNav{border:0;background:transparent;color:var(--muted);border-radius:13px;padding:8px 4px;font-size:10px;font-weight:850}.mNav span{display:block;font-size:20px;margin-bottom:2px}.mNav.active{background:var(--wine);color:#fff}}
@media(max-width:680px){.top{height:68px;padding:0 12px}.brandText b{max-width:calc(100vw - 110px);font-size:15px}.brandText span{font-size:10px}.panelMenuBtn{width:44px;padding:0;justify-content:center}.menuLabel{display:none}.panelMenu{position:fixed;top:76px;right:10px}.menuStatus .online{display:flex}.layout{padding:14px 10px 100px}.hero{border-radius:20px;padding:22px 19px}.hero h1{font-size:24px}.metrics{grid-template-columns:1fr 1fr;gap:9px}.metric{padding:14px}.metric strong{font-size:19px}.section{padding:14px;border-radius:18px}.sectionHead{align-items:flex-start;flex-direction:column}.toolbar{width:100%}.search{min-width:0;flex:1}.reservation{grid-template-columns:1fr auto;padding:13px}.dateCol{text-align:right}.hallCol{display:block}.amountCol{text-align:right}.actions{grid-column:1/-1}.customerGrid,.financeGrid,.twoCols{grid-template-columns:1fr}.formGrid{grid-template-columns:1fr}.formGroup.full{grid-column:auto}.modalWrap{padding:0;align-items:stretch}.modal{width:100%;height:100dvh;max-height:none;border-radius:0}.modalHead{padding:max(12px,env(safe-area-inset-top)) 14px 12px}.modalBody{padding:14px 14px 24px}.modalFoot{padding:12px 14px max(12px,env(safe-area-inset-bottom));flex-wrap:wrap}.modalFoot .dangerBtn{width:100%;order:2}.footRight{width:100%;margin:0}.footRight button{flex:1;min-height:46px}.close{width:48px;height:48px}.toast{bottom:92px}}
@media(max-width:680px){.customerAction{min-height:40px;display:inline-flex;align-items:center;justify-content:center}}
</style>
</head>
<body>
<div class="app">
<header class="top"><div class="brand"><div class="logo">NSX</div><div class="brandText"><b id="companyName">Salon Takip</b><span>NSX Düğün Salonu Pro · Canlı yönetim paneli</span></div></div><div class="topActions"><button type="button" class="panelMenuBtn" id="panelMenuBtn" aria-expanded="false" aria-controls="panelMenu"><span class="menuDots">⋮</span><span class="menuLabel">Panel İşlemleri</span></button><div class="panelMenu" id="panelMenu"><div class="menuStatus"><div class="menuStatusText"><b>Mobil panel oturumu</b><span>QR ile açılan güvenli firma bağlantısı</span></div><div class="online" id="onlineState"><span class="dot"></span><span>Bağlı</span></div></div><button type="button" class="menuAction" id="dashboardBtn"><span>⌂</span><span>Genel bakışa dön</span></button><button type="button" class="menuAction" id="refreshBtn"><span>↻</span><span>Verileri yenile</span></button><button type="button" class="menuAction" id="installAppBtn"><span>⇩</span><span>Telefona uygulama olarak kur</span></button><div class="menuDivider"></div><button type="button" class="menuAction danger" id="logoutBtn"><span>⇥</span><span>Güvenli çıkış</span></button><div class="menuHint">QR yalnızca ilk güvenli giriş içindir. Ana ekrana kurduktan sonra NSX Salon simgesinden doğrudan açabilirsiniz.</div></div></div></header>
<div class="layout"><aside class="side"><button class="navBtn active" data-tab="dashboard"><span class="navIcon">⌂</span>Genel Bakış</button><button class="navBtn" data-tab="reservations"><span class="navIcon">◫</span>Rezervasyonlar</button><button class="navBtn" data-tab="customers"><span class="navIcon">♙</span>Müşteriler</button><button class="navBtn" data-tab="finance"><span class="navIcon">₺</span>Finans</button></aside><main class="content" id="content"><div class="loading"><div><div class="spinner"></div>Salon bilgileri yükleniyor...</div></div></main></div>
<nav class="mobileNav"><button class="mNav active" data-tab="dashboard"><span>⌂</span>Özet</button><button class="mNav" data-tab="reservations"><span>◫</span>Rezervasyon</button><button class="mNav" data-tab="customers"><span>♙</span>Müşteri</button><button class="mNav" data-tab="finance"><span>₺</span>Finans</button></nav>
</div>
<div class="modalWrap" id="reservationModal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal"><div class="modalHead"><h2 id="modalTitle">Yeni Rezervasyon</h2><button type="button" class="close" id="modalClose" aria-label="Kapat">✕</button></div><form id="reservationForm" style="display:contents"><div class="modalBody"><div class="formGrid"><div class="formGroup"><div class="fieldLabelRow"><label>Müşteri</label><button type="button" class="miniAdd" id="newCustomerFromReservation">+ Yeni müşteri</button></div><select class="field" id="fCustomerName" required><option value="">Müşteri seçiniz</option></select><span class="fieldHint">Kayıtlı müşteri kartlarından seçim yapın.</span></div><div class="formGroup"><label>Telefon</label><input class="field" id="fPhone" inputmode="tel" maxlength="20" placeholder="Seçilen müşteriden otomatik gelir"></div><div class="formGroup"><label>Organizasyon tarihi</label><input class="field" id="fDate" type="date" required></div><div class="formGroup"><label>Saat</label><input class="field" id="fTime" type="time" required></div><div class="formGroup"><label>Organizasyon türü</label><input class="field" id="fOrganizationType" list="orgTypes" value="Düğün"><datalist id="orgTypes"><option>Düğün</option><option>Nişan</option><option>Kına</option><option>Sünnet</option><option>Toplantı</option></datalist></div><div class="formGroup"><label>Salon</label><select class="field" id="fHallName"></select></div><div class="formGroup"><label>Davetli sayısı</label><input class="field" id="fGuestCount" inputmode="numeric"></div><div class="formGroup"><label>Durum</label><select class="field" id="fStatus"><option>Opsiyonlu</option><option>Kesinleşti</option><option>Hazırlanıyor</option><option>Tamamlandı</option><option>İptal Edildi</option></select></div><div class="formGroup"><label>Toplam ücret</label><input class="field" id="fTotalAmount" type="number" min="0" step="0.01"></div><div class="formGroup"><label>İlk kapora / alınan ödeme</label><input class="field" id="fDepositAmount" type="number" min="0" step="0.01"></div><div class="formGroup full"><label>Notlar</label><textarea class="field area" id="fNotes" maxlength="2000"></textarea></div></div></div><div class="modalFoot"><button type="button" class="dangerBtn" id="cancelReservationBtn" style="display:none">Rezervasyonu İptal Et</button><div class="footRight"><button type="button" class="secondary" id="modalCloseBottom">Kapat</button><button type="submit" class="primary" id="saveReservationBtn">Kaydet</button></div></div></form></div></div>
<div class="modalWrap" id="financeModal" role="dialog" aria-modal="true" aria-labelledby="financeModalTitle"><div class="modal" style="width:min(620px,100%)"><div class="modalHead"><div><span class="modalTag" id="financeModalTag">CARİ İŞLEM</span><h2 id="financeModalTitle" style="margin-top:8px">Yeni Tahsilat</h2></div><button type="button" class="close" id="financeModalClose" aria-label="Kapat">✕</button></div><form id="financeForm" style="display:contents"><div class="modalBody"><div class="formGrid"><div class="formGroup full"><label>Müşteri</label><select class="field" id="financeCustomer" required></select><span class="fieldHint">İşlem seçilen müşterinin cari kartına anında kaydedilir.</span></div><div class="formGroup"><label>İşlem tarihi</label><input class="field" id="financeDate" type="date" required></div><div class="formGroup" id="paymentTypeGroup"><label>Ödeme tipi</label><select class="field" id="financePaymentType"><option>Nakit</option><option>Kredi Kartı</option><option>Havale / EFT</option><option>POS</option><option>Diğer</option></select></div><div class="formGroup full"><label>Tutar</label><input class="field moneyInput" id="financeAmount" type="number" min="0.01" step="0.01" inputmode="decimal" placeholder="0,00" required></div><div class="formGroup full"><label>Açıklama</label><textarea class="field area" id="financeDescription" maxlength="500" required placeholder="İşlemi daha sonra kolayca bulabileceğiniz kısa bir açıklama yazın"></textarea><span class="fieldHint"><span id="descriptionCount">0</span>/500 karakter</span></div></div></div><div class="modalFoot"><div class="fieldHint">Ctrl + Enter ile hızlı kaydedebilirsiniz.</div><div class="footRight"><button type="button" class="secondary" id="financeCancel">Vazgeç</button><button type="submit" class="primary" id="financeSave">Kaydet</button></div></div></form></div></div>
<div class="modalWrap customerModalWrap" id="customerModal" role="dialog" aria-modal="true" aria-labelledby="customerModalTitle"><div class="modal" style="width:min(680px,100%)"><div class="modalHead"><div><span class="modalTag">MÜŞTERİ KARTI</span><h2 id="customerModalTitle" style="margin-top:8px">Yeni Müşteri</h2></div><button type="button" class="close" id="customerModalClose" aria-label="Kapat">✕</button></div><form id="customerForm" style="display:contents"><div class="modalBody"><div class="formGrid"><div class="formGroup full"><label>Ad Soyad / Firma</label><input class="field" id="customerFullName" maxlength="180" autocomplete="name" placeholder="Müşteri adı veya firma unvanı" required></div><div class="formGroup"><label>Telefon</label><input class="field" id="customerPhone" inputmode="tel" maxlength="20" autocomplete="tel" placeholder="05xx xxx xx xx" required></div><div class="formGroup"><label>İkinci telefon</label><input class="field" id="customerSecondPhone" inputmode="tel" maxlength="20" placeholder="İsteğe bağlı"></div><div class="formGroup"><label>E-posta</label><input class="field" id="customerEmail" type="email" maxlength="180" autocomplete="email" placeholder="ornek@firma.com"></div><div class="formGroup"><label>TC / Vergi No</label><input class="field" id="customerIdentityNumber" inputmode="numeric" maxlength="30" placeholder="İsteğe bağlı"></div><div class="formGroup"><label>Durum</label><select class="field" id="customerStatus"><option>Aktif</option><option>Pasif</option></select></div><div class="formGroup full"><label>Adres</label><textarea class="field area" id="customerAddress" maxlength="600" autocomplete="street-address" placeholder="Adres bilgisi"></textarea></div><div class="formGroup full"><label>Not</label><textarea class="field area" id="customerNotes" maxlength="1000" placeholder="Görüşme, iletişim veya müşteriyle ilgili kısa not"></textarea></div><div class="formGroup full"><div class="customerFormNote">Ekleme ve düzenleme işlemleri buluta kaydedilir; masaüstü NSX Düğün Salonu Pro ilk senkronizasyonda otomatik güncellenir.</div></div></div></div><div class="modalFoot"><div class="fieldHint">Ad Soyad / Firma ve telefon alanları zorunludur.</div><div class="footRight"><button type="button" class="secondary" id="customerCancel">Vazgeç</button><button type="submit" class="primary" id="customerSave">Müşteriyi Kaydet</button></div></div></form></div></div>
<div class="connectionBanner" id="connectionBanner">İnternet bağlantısı bekleniyor. Verileriniz korunuyor.</div>
<div class="toast" id="toast"></div>
<script>
const state={tab:'dashboard',tenant:null,reservations:[],customers:[],finance:[],payments:[],expenses:[],halls:[],company:[],editing:null,editingCustomer:null,loading:false,lastChangeId:0,reservationCustomerMap:{},customerModalSource:'customers'};
let deferredInstallPrompt=null;
const isStandalone=()=>window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true;
const content=document.getElementById('content');
const csrf=()=>{const m=document.cookie.match(/(?:^|; )NSX\.SalonTakip\.Csrf=([^;]*)/);return m?decodeURIComponent(m[1]):''};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function num(v){if(typeof v==='number')return Number.isFinite(v)?v:0;let s=String(v??'').trim().replace(/[^0-9,.-]/g,'');if(!s)return 0;const comma=s.lastIndexOf(','),dot=s.lastIndexOf('.');if(comma>=0&&dot>=0){if(comma>dot)s=s.replace(/\./g,'').replace(',','.');else s=s.replace(/,/g,'')}else if(comma>=0)s=s.replace(',','.');const n=Number(s);return Number.isFinite(n)?n:0}
const money=v=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:0}).format(num(v));
const today=()=>{const d=new Date();const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return y+'-'+m+'-'+day};
function prop(o,...names){if(!o)return'';for(const n of names){if(Object.prototype.hasOwnProperty.call(o,n))return o[n]}const keys=Object.keys(o);for(const n of names){const k=keys.find(x=>x.toLocaleLowerCase('tr-TR')===String(n).toLocaleLowerCase('tr-TR'));if(k)return o[k]}return''}
function parseItems(items){return(items||[]).map(i=>{let p={};try{p=JSON.parse(prop(i,'payloadJson','PayloadJson')||'{}')}catch{}return{...p,__id:String(prop(i,'id','Id')||''),__updatedAt:prop(i,'updatedAt','UpdatedAt'),__version:prop(i,'version','Version')}})}
function dateOnly(v){if(!v)return'';const s=String(v);return s.length>=10?s.slice(0,10):s}
function timeOnly(v){if(!v)return'';const s=String(v);if(s.includes('T'))return s.slice(11,16);return s.slice(0,5)}
function dateText(v){const raw=dateOnly(v);if(!raw)return'-';const d=new Date(raw+'T00:00:00');return isNaN(d)?raw:d.toLocaleDateString('tr-TR',{day:'2-digit',month:'short',year:'numeric'})}
function statusClass(v){const s=String(v||'').toLocaleLowerCase('tr-TR');if(s.includes('iptal'))return'danger';if(s.includes('tamam')||s.includes('kesin'))return'ok';if(s.includes('opsiyon')||s.includes('hazır'))return'warn';return''}
function isPassive(r){const s=String(prop(r,'Status')).toLocaleLowerCase('tr-TR');return s.includes('tamam')||s.includes('iptal')||s.includes('pasif')}
function reservationDate(r){return dateOnly(prop(r,'Date','OrganizationDate','ReservationDate'))}
function reservationTime(r){return timeOnly(prop(r,'Time','OrganizationTime'))||'20:00'}
function reservationNumericId(r){const value=num(prop(r,'Id'));if(value>0)return value;const raw=String(r?.__id||'');return /^\d+$/.test(raw)?Number(raw):0}
function byReservation(items,r){const id=reservationNumericId(r);return id>0?items.filter(x=>num(prop(x,'ReservationId'))===id):[]}
function reservationFinancials(r){const movements=byReservation(state.finance,r);const paymentRows=byReservation(state.payments,r);const debt=movements.reduce((s,x)=>s+num(prop(x,'DebtAmount')),0);const movementPaid=movements.reduce((s,x)=>s+num(prop(x,'PaymentAmount')),0);const paymentPaid=paymentRows.reduce((s,x)=>s+num(prop(x,'Amount')),0);const total=debt>0?debt:num(prop(r,'TotalAmount'));const paid=movementPaid>0?movementPaid:(paymentPaid>0?paymentPaid:num(prop(r,'DepositAmount','PaidAmount')));return{total,paid,remaining:Math.max(0,total-paid)}}
function customerBalance(c){const cid=num(prop(c,'Id'))||(/^[0-9]+$/.test(c.__id||'')?Number(c.__id):0);const rows=cid>0?state.finance.filter(x=>num(prop(x,'CustomerId'))===cid):[];if(rows.length)return rows.reduce((s,x)=>s+num(prop(x,'DebtAmount'))-num(prop(x,'PaymentAmount')),0);const explicit=prop(c,'RemainingBalance');return explicit!==''?num(explicit):num(prop(c,'TotalAmount'))-num(prop(c,'PaidAmount'))}
function financeSummary(){if(state.finance.length){const total=state.finance.reduce((s,x)=>s+num(prop(x,'DebtAmount')),0);const paid=state.finance.reduce((s,x)=>s+num(prop(x,'PaymentAmount')),0);return{total,paid,remaining:total-paid,expenses:state.expenses.reduce((s,x)=>s+num(prop(x,'Amount')),0)}}const total=state.reservations.reduce((s,r)=>s+num(prop(r,'TotalAmount')),0);const paid=state.reservations.reduce((s,r)=>s+num(prop(r,'DepositAmount','PaidAmount')),0);return{total,paid,remaining:total-paid,expenses:state.expenses.reduce((s,x)=>s+num(prop(x,'Amount')),0)}}
function showToast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.remove('show'),3400)}
async function api(url,options={}){const headers={'Accept':'application/json',...(options.headers||{})};if(options.method&&options.method!=='GET'){headers['Content-Type']='application/json';headers['X-NSX-CSRF']=csrf()}const r=await fetch(url,{credentials:'same-origin',cache:'no-store',...options,headers});if(r.status===401){location.href='/salontakip';throw new Error('Oturum sona erdi.')}if(!r.ok){let msg=r.status===403?'Güvenlik doğrulaması başarısız. Sayfayı yenileyin.':'İşlem gerçekleştirilemedi.';try{const j=await r.json();msg=j.message||j.detail||msg}catch{}throw new Error(msg)}return r.status===204?null:r.json()}
async function load(show=true){if(state.loading)return;state.loading=true;if(show)content.innerHTML='<div class="loading"><div><div class="spinner"></div>Salon bilgileri yükleniyor...</div></div>';try{const b=await api('/api/salontakip/mobile/bootstrap');state.tenant=b.tenant;state.lastChangeId=b.lastChangeId||0;state.reservations=parseItems(b.data.reservations);state.customers=parseItems(b.data.customers);state.finance=parseItems(b.data.finance);state.payments=parseItems(b.data.payments);state.expenses=parseItems(b.data.expenses);state.halls=parseItems(b.data.halls);state.company=parseItems(b.data.company);document.getElementById('companyName').textContent=state.tenant.companyName||'Salon Takip';render()}catch(e){content.innerHTML='<section class="section"><div class="empty"><div class="emptyIcon">⚠️</div><b>Bilgiler alınamadı</b><p>'+esc(e.message)+'</p><button class="primary" onclick="load()">Tekrar Dene</button></div></section>'}finally{state.loading=false}}
function setTab(tab){state.tab=tab;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));render()}
function hero(title,sub){return'<section class="hero"><small>NSX DÜĞÜN SALONU PRO</small><h1>'+esc(title)+'</h1><p>'+esc(sub)+'</p></section>'}
function metrics(){const t=today();const active=state.reservations.filter(r=>!isPassive(r));const todayCount=state.reservations.filter(r=>reservationDate(r)===t&&!String(prop(r,'Status')).toLocaleLowerCase('tr-TR').includes('iptal')).length;const upcoming=active.filter(r=>reservationDate(r)>=t).length;const f=financeSummary();return'<div class="metrics"><div class="metric"><div class="metricTop"><div class="metricIcon">📅</div></div><label>BUGÜNKÜ ORGANİZASYON</label><strong>'+todayCount+'</strong></div><div class="metric"><div class="metricTop"><div class="metricIcon">✨</div></div><label>YAKLAŞAN AKTİF</label><strong>'+upcoming+'</strong></div><div class="metric"><div class="metricTop"><div class="metricIcon">👥</div></div><label>TOPLAM MÜŞTERİ</label><strong>'+state.customers.length+'</strong></div><div class="metric"><div class="metricTop"><div class="metricIcon">₺</div></div><label>KALAN TAHSİLAT</label><strong>'+money(f.remaining)+'</strong></div></div>'}
function reservationRow(r){const name=prop(r,'CustomerName','FullName')||'İsimsiz müşteri';const phone=prop(r,'Phone');const status=prop(r,'Status')||'Opsiyonlu';const f=reservationFinancials(r);return'<article class="reservation"><div><div class="resName">'+esc(name)+'</div><div class="sub">'+esc(phone||prop(r,'OrganizationType')||'Telefon yok')+'</div></div><div class="dateCol"><b>'+esc(dateText(reservationDate(r)))+'</b><div class="sub">'+esc(reservationTime(r))+'</div></div><div class="hallCol"><b>'+esc(prop(r,'HallName')||'-')+'</b><div class="sub">'+esc(prop(r,'OrganizationType')||'Organizasyon')+'</div></div><div class="amountCol"><div class="amount">'+esc(money(f.total))+'</div><div class="sub">Alınan '+esc(money(f.paid))+' · Kalan '+esc(money(f.remaining))+'</div></div><div class="actions"><span class="badge '+statusClass(status)+'">'+esc(status)+'</span><button class="ghost" data-edit="'+esc(r.__id)+'">Düzenle</button></div></article>'}
function renderDashboard(){const sorted=[...state.reservations].filter(r=>!isPassive(r)&&reservationDate(r)>=today()).sort((a,b)=>(reservationDate(a)+reservationTime(a)).localeCompare(reservationDate(b)+reservationTime(b))).slice(0,6);content.innerHTML=hero('Hoş geldiniz','Salonun güncel durumu, müşteriler ve gerçek cari bakiye tek ekranda.')+metrics()+'<section class="section"><div class="sectionHead"><div><h2>Yaklaşan Organizasyonlar</h2><div class="muted" style="font-size:12px;margin-top:4px">En yakın aktif rezervasyonlar</div></div><div class="toolbar"><button class="secondary" id="dashboardNewCustomer">+ Yeni Müşteri</button><button class="primary" id="newReservation">+ Yeni Rezervasyon</button></div></div><div class="list">'+(sorted.length?sorted.map(reservationRow).join(''):'<div class="empty"><div class="emptyIcon">📆</div>Yaklaşan aktif rezervasyon bulunmuyor.</div>')+'</div></section>';bindRows();document.getElementById('dashboardNewCustomer').onclick=()=>openCustomerModal('dashboard');document.getElementById('newReservation').onclick=()=>openReservation()}
function renderReservations(){content.innerHTML=hero('Rezervasyon Yönetimi','Aktif ve pasif tüm organizasyonları arayın, güncelleyin ve yeni kayıt oluşturun.')+'<section class="section"><div class="sectionHead"><div><h2>Tüm Rezervasyonlar</h2><div class="muted" style="font-size:12px;margin-top:4px">'+state.reservations.length+' kayıt</div></div><div class="toolbar"><input id="resSearch" class="search" placeholder="Müşteri, telefon veya salon ara"><select id="resFilter" class="select"><option value="all">Tümü</option><option value="active">Aktif</option><option value="passive">Pasif</option></select><button class="primary" id="newReservation">+ Yeni</button></div></div><div id="reservationList" class="list"></div></section>';const draw=()=>{const q=document.getElementById('resSearch').value.toLocaleLowerCase('tr-TR');const f=document.getElementById('resFilter').value;const rows=[...state.reservations].filter(r=>{const text=[prop(r,'CustomerName'),prop(r,'Phone'),prop(r,'HallName'),prop(r,'OrganizationType'),prop(r,'Status')].join(' ').toLocaleLowerCase('tr-TR');return(!q||text.includes(q))&&(f==='all'||(f==='active'&&!isPassive(r))||(f==='passive'&&isPassive(r)))}).sort((a,b)=>(reservationDate(b)+reservationTime(b)).localeCompare(reservationDate(a)+reservationTime(a)));document.getElementById('reservationList').innerHTML=rows.length?rows.map(reservationRow).join(''):'<div class="empty"><div class="emptyIcon">🔎</div>Aramaya uygun rezervasyon bulunamadı.</div>';bindRows()};document.getElementById('resSearch').oninput=draw;document.getElementById('resFilter').onchange=draw;document.getElementById('newReservation').onclick=()=>openReservation();draw()}
function initials(name){return String(name||'M').split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toLocaleUpperCase('tr-TR')}
function renderCustomers(){const cards=state.customers.map(c=>{const name=prop(c,'FullName','CustomerName')||'İsimsiz müşteri';const phone=String(prop(c,'Phone')||'');const digits=normalizePhone(phone);const balance=customerBalance(c);const status=prop(c,'Status')||'Aktif';return'<article class="customer" data-customer-search="'+esc([name,phone,prop(c,'SecondPhone'),prop(c,'Email'),prop(c,'IdentityNumber')].join(' ').toLocaleLowerCase('tr-TR'))+'"><div class="customerTop"><div><div class="avatar">'+esc(initials(name))+'</div><b>'+esc(name)+'</b></div><span class="badge '+(String(status).toLocaleLowerCase('tr-TR').includes('pasif')?'danger':'ok')+'">'+esc(status)+'</span></div><div class="phone">'+esc(phone||'Telefon girilmemiş')+'</div><div class="phone">'+esc(prop(c,'Email')||prop(c,'Address')||'')+'</div><div class="balance"><span>Güncel cari bakiye</span><strong>'+esc(money(balance))+'</strong></div><div class="customerActions">'+(digits?'<a class="customerAction" href="tel:'+esc(digits)+'">Ara</a><a class="customerAction" target="_blank" rel="noopener" href="https://wa.me/90'+esc(digits.replace(/^0/,''))+'">WhatsApp</a>':'')+'<button type="button" class="customerAction" data-customer-edit="'+esc(c.__id)+'">Düzenle</button><button type="button" class="customerAction delete" data-customer-delete="'+esc(c.__id)+'">Sil</button></div></article>'}).join('');content.innerHTML=hero('Müşteriler','Masaüstü ve web panelinden oluşturulan müşteri kartlarını tek yerden yönetin.')+'<section class="section"><div class="sectionHead"><div><h2>Müşteri Kartları</h2><div class="muted" style="font-size:12px;margin-top:4px">'+state.customers.length+' müşteri</div></div><div class="toolbar"><input id="customerSearch" class="search" placeholder="Müşteri, telefon veya e-posta ara"><button class="primary" id="newCustomer">+ Yeni Müşteri</button></div></div><div id="customerGrid" class="customerGrid">'+(cards||'<div class="empty"><div class="emptyIcon">👤</div>Henüz müşteri bulunmuyor. İlk müşteriyi web panelinden ekleyebilirsiniz.</div>')+'</div></section>';document.getElementById('customerSearch').oninput=e=>{const q=e.target.value.toLocaleLowerCase('tr-TR');document.querySelectorAll('.customer').forEach(el=>el.style.display=(el.dataset.customerSearch||'').includes(q)?'block':'none')};document.querySelectorAll('[data-customer-edit]').forEach(b=>b.onclick=()=>openCustomerModal('customers',b.dataset.customerEdit));document.querySelectorAll('[data-customer-delete]').forEach(b=>b.onclick=()=>deleteCustomer(b.dataset.customerDelete));document.getElementById('newCustomer').onclick=()=>openCustomerModal('customers')}
function renderFinance(){const f=financeSummary();const ratio=f.total?Math.max(0,Math.min(100,Math.round(f.paid/f.total*100))):0;const recentPayments=[...state.payments].sort((a,b)=>String(prop(b,'Date')).localeCompare(String(prop(a,'Date')))).slice(0,8);const recentExpenses=[...state.expenses].sort((a,b)=>String(prop(b,'Date')).localeCompare(String(prop(a,'Date')))).slice(0,8);const paymentHtml=recentPayments.length?recentPayments.map(x=>'<div class="quickRow"><div><b>'+esc(prop(x,'CustomerName')||prop(x,'Description')||'Tahsilat')+'</b><div class="sub">'+esc(dateText(prop(x,'Date')))+' · '+esc(prop(x,'PaymentType')||'')+'</div></div><b style="color:var(--ok)">'+esc(money(prop(x,'Amount')))+'</b></div>').join(''):'<div class="empty">Tahsilat kaydı bulunmuyor.</div>';const expenseHtml=recentExpenses.length?recentExpenses.map(x=>'<div class="quickRow"><div><b>'+esc(prop(x,'Category')||'Gider')+'</b><div class="sub">'+esc(prop(x,'Description')||dateText(prop(x,'Date')))+'</div></div><b style="color:var(--danger)">'+esc(money(prop(x,'Amount')))+'</b></div>').join(''):'<div class="empty">Gider kaydı bulunmuyor.</div>';content.innerHTML=hero('Finans Özeti','Cari hareketler, sonradan girilen tahsilatlar ve giderler birlikte hesaplanır.')+'<div class="metrics"><div class="metric"><div class="metricIcon">📄</div><label>TOPLAM BORÇ / SÖZLEŞME</label><strong>'+esc(money(f.total))+'</strong></div><div class="metric"><div class="metricIcon">✓</div><label>TOPLAM TAHSİLAT</label><strong>'+esc(money(f.paid))+'</strong></div><div class="metric"><div class="metricIcon">₺</div><label>KALAN BAKİYE</label><strong>'+esc(money(f.remaining))+'</strong></div><div class="metric"><div class="metricIcon">↘</div><label>TOPLAM GİDER</label><strong>'+esc(money(f.expenses))+'</strong></div></div><section class="section"><div class="sectionHead"><h2>Tahsilat Performansı</h2><span class="badge ok">%'+ratio+' tahsil edildi</span></div><div class="progressBox"><div class="progress"><span style="width:'+ratio+'%"></span></div><div style="display:flex;justify-content:space-between;font-size:13px;gap:10px"><span class="muted">Alınan: '+esc(money(f.paid))+'</span><b style="color:var(--danger)">Kalan: '+esc(money(f.remaining))+'</b></div></div></section><div class="twoCols"><section class="section"><div class="sectionHead"><h2>Son Tahsilatlar</h2><span class="badge">'+state.payments.length+' kayıt</span></div><div class="quickList">'+paymentHtml+'</div></section><section class="section"><div class="sectionHead"><h2>Son Giderler</h2><span class="badge">'+state.expenses.length+' kayıt</span></div><div class="quickList">'+expenseHtml+'</div></section></div>'}
function enhanceFinanceActions(){const head=content.querySelector('.sectionHead');if(!head)return;const box=document.createElement('div');box.className='toolbar';box.innerHTML='<button class="primary" id="addPaymentBtn">+ Tahsilat</button><button class="secondary" id="addDebtBtn">+ Borç</button>';head.appendChild(box);document.getElementById('addPaymentBtn').onclick=()=>openFinanceModal('payment');document.getElementById('addDebtBtn').onclick=()=>openFinanceModal('debt')}
let financeKind='payment';function openFinanceModal(kind){if(!state.customers.length){showToast('Önce müşteri kaydı bulunmalıdır.');return}financeKind=kind;const payment=kind==='payment';document.getElementById('financeModalTitle').textContent=payment?'Yeni Tahsilat':'Yeni Borç Kaydı';document.getElementById('financeModalTag').textContent=payment?'TAHSİLAT':'BORÇ';document.getElementById('paymentTypeGroup').style.display=payment?'grid':'none';const select=document.getElementById('financeCustomer');select.innerHTML='<option value="">Müşteri seçiniz</option>'+[...state.customers].sort((a,b)=>String(prop(a,'FullName')).localeCompare(String(prop(b,'FullName'),'tr'))).map(c=>'<option value="'+esc(c.__id)+'">'+esc(prop(c,'FullName','CustomerName')||'İsimsiz')+' · '+esc(prop(c,'Phone')||'Telefon yok')+' · Bakiye '+esc(money(customerBalance(c)))+'</option>').join('');document.getElementById('financeDate').value=today();document.getElementById('financeAmount').value='';document.getElementById('financeDescription').value=payment?'Web panel tahsilatı':'Web panel borç kaydı';document.getElementById('descriptionCount').textContent=document.getElementById('financeDescription').value.length;document.getElementById('financeModal').classList.add('show');document.body.style.overflow='hidden';setTimeout(()=>select.focus(),60)}
function closeFinanceModal(){document.getElementById('financeModal').classList.remove('show');document.body.style.overflow=document.querySelector('#reservationModal.show,#customerModal.show')?'hidden':''}
function normalizePhone(value){return String(value||'').replace(/\D/g,'')}
function openCustomerModal(source='customers',id=''){state.customerModalSource=source;state.editingCustomer=id?state.customers.find(c=>c.__id===id):null;const c=state.editingCustomer||{};document.getElementById('customerForm').reset();document.getElementById('customerModalTitle').textContent=state.editingCustomer?'Müşteriyi Düzenle':'Yeni Müşteri';document.getElementById('customerFullName').value=prop(c,'FullName','CustomerName')||'';document.getElementById('customerPhone').value=prop(c,'Phone')||'';document.getElementById('customerSecondPhone').value=prop(c,'SecondPhone','Phone2')||'';document.getElementById('customerEmail').value=prop(c,'Email')||'';document.getElementById('customerIdentityNumber').value=prop(c,'IdentityNumber','TaxNumber')||'';document.getElementById('customerStatus').value=prop(c,'Status')||'Aktif';document.getElementById('customerAddress').value=prop(c,'Address')||'';document.getElementById('customerNotes').value=prop(c,'Notes','Note')||'';document.getElementById('customerSave').textContent=state.editingCustomer?'Değişiklikleri Kaydet':'Müşteriyi Kaydet';document.getElementById('customerModal').classList.add('show');document.body.style.overflow='hidden';setTimeout(()=>document.getElementById('customerFullName').focus(),70)}
function closeCustomerModal(){document.getElementById('customerModal').classList.remove('show');document.body.style.overflow=document.querySelector('#reservationModal.show,#financeModal.show')?'hidden':'';state.editingCustomer=null}
function customerReferences(c){const numeric=customerNumericId(c),cloud=String(c.__id||'');const linked=x=>(numeric>0&&num(prop(x,'CustomerId'))===numeric)||(cloud&&String(prop(x,'CustomerCloudId')||'')===cloud);return{reservations:state.reservations.filter(linked).length,finance:state.finance.filter(linked).length,payments:state.payments.filter(linked).length}}
async function deleteCustomer(id){const c=state.customers.find(x=>x.__id===id);if(!c)return;const refs=customerReferences(c);if(refs.reservations||refs.finance||refs.payments){showToast('Bu müşteriye bağlı rezervasyon veya cari hareket var. Veri bütünlüğü için önce bağlı kayıtları kaldırın.');return}const name=String(prop(c,'FullName','CustomerName')||'müşteri');if(!confirm(name+' müşteri kartı kalıcı olarak silinsin mi?'))return;try{await api('/api/salontakip/mobile/data/customer/'+encodeURIComponent(id),{method:'DELETE'});showToast('Müşteri silindi. Değişiklik masaüstüne otomatik aktarılacak.');await load(false)}catch(err){showToast(err.message||'Müşteri silinemedi.')}}
async function saveCustomer(e){e.preventDefault();const save=document.getElementById('customerSave');if(save.disabled)return;const editing=state.editingCustomer;const fullName=document.getElementById('customerFullName').value.trim();const phone=document.getElementById('customerPhone').value.trim();const secondPhone=document.getElementById('customerSecondPhone').value.trim();const phoneDigits=normalizePhone(phone);const email=document.getElementById('customerEmail').value.trim().toLowerCase();const identityNumber=document.getElementById('customerIdentityNumber').value.trim();const status=document.getElementById('customerStatus').value;const address=document.getElementById('customerAddress').value.trim();const notes=document.getElementById('customerNotes').value.trim();if(fullName.length<2){showToast('Müşteri adı en az 2 karakter olmalıdır.');return}if(phoneDigits.length<10||phoneDigits.length>11){showToast('Geçerli bir telefon numarası giriniz.');return}const duplicate=state.customers.find(c=>c!==editing&&normalizePhone(prop(c,'Phone'))===phoneDigits);if(duplicate){showToast('Bu telefon numarasıyla kayıtlı bir müşteri zaten var: '+String(prop(duplicate,'FullName','CustomerName')||''));return}const source=state.customerModalSource;save.disabled=true;save.textContent='Kaydediliyor...';try{let savedId='';if(editing){const payload={...editing};Object.keys(payload).filter(k=>k.startsWith('__')).forEach(k=>delete payload[k]);Object.assign(payload,{FullName:fullName,CustomerName:fullName,Name:fullName,Phone:phone,PhoneNumber:phone,Telephone:phone,MobilePhone:phone,SecondPhone:secondPhone,Phone2:secondPhone,Email:email,EmailAddress:email,Address:address,IdentityNumber:identityNumber,TaxNumber:identityNumber,Status:status,Notes:notes,Note:notes,UpdatedAt:new Date().toISOString(),UpdatedDate:new Date().toISOString(),SyncOrigin:'MOBILE-WEB'});await api('/api/salontakip/mobile/data/customer/'+encodeURIComponent(editing.__id),{method:'PUT',body:JSON.stringify({payloadJson:JSON.stringify(payload),sourceDeviceId:'MOBILE-WEB',sourceUser:'Mobil Panel'})});savedId=editing.__id}else{const result=await api('/api/salontakip/mobile/customers',{method:'POST',body:JSON.stringify({fullName,phone,secondPhone,email,address,identityNumber,status,notes})});if(!result||result.success!==true||!result.entityId)throw new Error(result?.message||'Sunucu müşteri kaydını doğrulamadı.');savedId=result.entityId}const persistedRows=await api('/api/salontakip/mobile/data/customer?take=5000');state.customers=parseItems(persistedRows);const savedCustomer=state.customers.find(c=>String(c.__id||'')===String(savedId));if(!savedCustomer)throw new Error('Müşteri kaydı sunucudan tekrar okunamadı. İşlem doğrulanamadı.');closeCustomerModal();if(source==='reservation'&&document.getElementById('reservationModal').classList.contains('show')){fillReservationCustomers(state.editing||{},savedId);syncReservationCustomerPhone();setTimeout(()=>document.getElementById('fDate').focus(),60)}else{render()}showToast(editing?'Müşteri güncellendi. Değişiklik masaüstüne aktarılacak.':'Müşteri sunucuya kaydedildi. Masaüstü ilk senkronizasyonda otomatik alacak.')}catch(err){showToast(err.message||'Müşteri kaydedilemedi.')}finally{save.disabled=false;save.textContent=state.editingCustomer?'Değişiklikleri Kaydet':'Müşteriyi Kaydet'}}
async function saveFinanceOperation(e){e.preventDefault();const customer=state.customers.find(c=>c.__id===document.getElementById('financeCustomer').value);const amount=num(document.getElementById('financeAmount').value);const description=document.getElementById('financeDescription').value.trim();if(!customer){showToast('Müşteri seçiniz.');return}if(amount<=0){showToast('Tutar sıfırdan büyük olmalıdır.');return}if(!description){showToast('Açıklama zorunludur.');return}const save=document.getElementById('financeSave');save.disabled=true;save.textContent='Kaydediliyor...';const customerId=num(prop(customer,'Id'))||num(customer.__id);const id='WEB-FIN-'+Date.now()+'-'+Math.random().toString(36).slice(2,8);const paymentType=financeKind==='payment'?document.getElementById('financePaymentType').value:'-';const payload={CustomerId:customerId,CustomerCloudId:String(customer.__id||''),CustomerName:prop(customer,'FullName','CustomerName'),ReservationId:0,Date:document.getElementById('financeDate').value+'T12:00:00',MovementType:financeKind==='payment'?'Web Tahsilat':'Web Borç',Description:description,PaymentType:paymentType,DebtAmount:financeKind==='debt'?amount:0,PaymentAmount:financeKind==='payment'?amount:0};try{await api('/api/salontakip/mobile/data/finance/'+encodeURIComponent(id),{method:'POST',body:JSON.stringify({payloadJson:JSON.stringify(payload),sourceDeviceId:'MOBILE-WEB',sourceUser:'Mobil Panel'})});if(financeKind==='payment'){const payment={CustomerId:customerId,CustomerName:payload.CustomerName,ReservationId:0,Date:payload.Date,Description:description,PaymentType:paymentType,Amount:amount};await api('/api/salontakip/mobile/data/payment/'+encodeURIComponent('WEB-PAY-'+id),{method:'POST',body:JSON.stringify({payloadJson:JSON.stringify(payment),sourceDeviceId:'MOBILE-WEB',sourceUser:'Mobil Panel'})})}closeFinanceModal();showToast(financeKind==='payment'?'Tahsilat başarıyla kaydedildi.':'Borç başarıyla kaydedildi.');await load(false)}catch(err){showToast(err.message)}finally{save.disabled=false;save.textContent='Kaydet'}}
function render(){if(state.tab==='reservations')renderReservations();else if(state.tab==='customers')renderCustomers();else if(state.tab==='finance'){renderFinance();enhanceFinanceActions()}else renderDashboard()}
function bindRows(){document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openReservation(b.dataset.edit))}
function fillHalls(selected=''){const select=document.getElementById('fHallName');let names=state.halls.map(h=>prop(h,'Name','HallName')).filter(Boolean);if(!names.length&&state.company.length){const embedded=prop(state.company[0],'Halls');if(Array.isArray(embedded))names=embedded.map(x=>typeof x==='string'?x:prop(x,'Name')).filter(Boolean)}if(!names.length)names=['Salon 1'];if(selected&&!names.includes(selected))names.push(selected);select.innerHTML=names.map(n=>'<option '+(n===selected?'selected':'')+'>'+esc(n)+'</option>').join('')}
function customerNumericId(c){const value=num(prop(c,'Id','CustomerId'));if(value>0)return value;const raw=String(c?.__id||'');return /^\d+$/.test(raw)?Number(raw):0}
function fillReservationCustomers(reservation={},preferredEntityId=''){const select=document.getElementById('fCustomerName');const rows=[...state.customers].sort((a,b)=>String(prop(a,'FullName','CustomerName')).localeCompare(String(prop(b,'FullName','CustomerName')),'tr'));state.reservationCustomerMap={};let options='<option value="">Müşteri seçiniz</option>';rows.forEach((c,index)=>{const key='customer-'+index;state.reservationCustomerMap[key]=c;const name=prop(c,'FullName','CustomerName')||'İsimsiz müşteri';const phone=prop(c,'Phone')||'Telefon yok';options+='<option value="'+key+'">'+esc(name)+' · '+esc(phone)+'</option>'});const reservationId=num(prop(reservation,'CustomerId'));const reservationName=String(prop(reservation,'CustomerName')||'').trim();let selectedKey='';for(const [key,c] of Object.entries(state.reservationCustomerMap)){if((preferredEntityId&&String(c.__id||'')===String(preferredEntityId))||(reservationId>0&&customerNumericId(c)===reservationId)||(!reservationId&&reservationName&&String(prop(c,'FullName','CustomerName')).trim().toLocaleLowerCase('tr-TR')===reservationName.toLocaleLowerCase('tr-TR'))){selectedKey=key;break}}if(!selectedKey&&reservationName){selectedKey='existing-customer';state.reservationCustomerMap[selectedKey]={Id:reservationId,FullName:reservationName,Phone:prop(reservation,'Phone')||''};options+='<option value="'+selectedKey+'">'+esc(reservationName)+' · '+esc(prop(reservation,'Phone')||'Telefon yok')+'</option>'}select.innerHTML=options;select.value=selectedKey}
function selectedReservationCustomer(){return state.reservationCustomerMap[document.getElementById('fCustomerName').value]||null}
function syncReservationCustomerPhone(){const customer=selectedReservationCustomer();document.getElementById('fPhone').value=customer?String(prop(customer,'Phone')||''):''}
function openReservation(id=''){state.editing=id?state.reservations.find(r=>r.__id===id):null;const r=state.editing||{};document.getElementById('modalTitle').textContent=state.editing?'Rezervasyonu Düzenle':'Yeni Rezervasyon';fillReservationCustomers(r);document.getElementById('fPhone').value=prop(r,'Phone')||prop(selectedReservationCustomer(),'Phone')||'';document.getElementById('fDate').value=reservationDate(r)||today();document.getElementById('fTime').value=reservationTime(r)||'20:00';document.getElementById('fOrganizationType').value=prop(r,'OrganizationType')||'Düğün';fillHalls(prop(r,'HallName')||'');document.getElementById('fGuestCount').value=prop(r,'GuestCount')||'';document.getElementById('fStatus').value=prop(r,'Status')||'Opsiyonlu';document.getElementById('fTotalAmount').value=num(prop(r,'TotalAmount'))||'';document.getElementById('fDepositAmount').value=num(prop(r,'DepositAmount','PaidAmount'))||'';document.getElementById('fNotes').value=prop(r,'Notes')||'';document.getElementById('cancelReservationBtn').style.display=state.editing?'block':'none';document.getElementById('reservationModal').classList.add('show');document.body.style.overflow='hidden';setTimeout(()=>document.getElementById('fCustomerName').focus(),80)}
function closeModal(){document.getElementById('reservationModal').classList.remove('show');document.body.style.overflow=document.querySelector('#financeModal.show,#customerModal.show')?'hidden':'';state.editing=null}
async function saveReservation(e){e.preventDefault();const saveBtn=document.getElementById('saveReservationBtn');if(saveBtn.disabled)return;const old=state.editing||{};const customer=selectedReservationCustomer();if(!customer){showToast('Lütfen kayıtlı bir müşteri seçiniz.');return}const payload={...old};Object.keys(payload).filter(k=>k.startsWith('__')).forEach(k=>delete payload[k]);payload.Id=Number(prop(old,'Id'))||0;payload.CustomerId=customerNumericId(customer)||Number(prop(old,'CustomerId'))||0;payload.CustomerCloudId=String(customer.__id||prop(old,'CustomerCloudId')||'');payload.CustomerName=String(prop(customer,'FullName','CustomerName')||'').trim();payload.Phone=document.getElementById('fPhone').value.trim()||String(prop(customer,'Phone')||'').trim();payload.Date=document.getElementById('fDate').value+'T00:00:00';payload.Time=document.getElementById('fTime').value+':00';payload.OrganizationType=document.getElementById('fOrganizationType').value.trim();payload.HallName=document.getElementById('fHallName').value;payload.GuestCount=document.getElementById('fGuestCount').value.trim();payload.Status=document.getElementById('fStatus').value;payload.TotalAmount=num(document.getElementById('fTotalAmount').value);payload.DepositAmount=num(document.getElementById('fDepositAmount').value);payload.Notes=document.getElementById('fNotes').value.trim();if(payload.DepositAmount>payload.TotalAmount&&payload.TotalAmount>0){showToast('Alınan ödeme toplam ücretten büyük olamaz.');return}const id=state.editing?state.editing.__id:'WEB-'+Date.now()+'-'+Math.random().toString(36).slice(2,8);saveBtn.disabled=true;saveBtn.textContent='Kaydediliyor...';try{const result=await api('/api/salontakip/mobile/data/reservation/'+encodeURIComponent(id),{method:'POST',body:JSON.stringify({payloadJson:JSON.stringify(payload),sourceDeviceId:'MOBILE-WEB',sourceUser:'Mobil Panel'})});closeModal();showToast('Web kaydı tamamlandı. Masaüstü senkronunda otomatik işlenecek.');await load(false)}catch(err){showToast(err.message)}finally{saveBtn.disabled=false;saveBtn.textContent='Kaydet'}}
async function cancelReservation(){if(!state.editing)return;document.getElementById('fStatus').value='İptal Edildi';document.getElementById('reservationForm').requestSubmit()}
async function logout(){if(!confirm('Güvenli çıkış yapılsın mı? Tekrar giriş için masaüstü programdan yeni QR kod okutmanız gerekir.'))return;try{await api('/salontakip/cikis',{method:'POST',body:'{}'})}catch{}location.href='/salontakip'}
async function installApp(){closePanelMenu();if(isStandalone()){showToast('NSX Salon zaten uygulama olarak açık.');return}if(deferredInstallPrompt){deferredInstallPrompt.prompt();const choice=await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;if(choice.outcome==='accepted')showToast('NSX Salon ana ekranınıza kuruluyor.');return}const ios=/iphone|ipad|ipod/i.test(navigator.userAgent);alert(ios?'iPhone / iPad Chrome: Adres çubuğunun yanındaki Paylaş simgesine dokunun, “Ana Ekrana Ekle” seçeneğini seçin ve Ekle deyin.':'Android Chrome: Sağ üstteki üç nokta menüsünü açın, “Ana ekrana ekle” ve ardından “Yükle” seçeneğine dokunun. QR sadece ilk giriş içindir.')}
function closePanelMenu(){const menu=document.getElementById('panelMenu'),btn=document.getElementById('panelMenuBtn');menu.classList.remove('show');btn.setAttribute('aria-expanded','false')}function togglePanelMenu(){const menu=document.getElementById('panelMenu'),btn=document.getElementById('panelMenuBtn');const show=!menu.classList.contains('show');menu.classList.toggle('show',show);btn.setAttribute('aria-expanded',show?'true':'false')}function updateConnection(){const online=navigator.onLine;document.getElementById('connectionBanner').classList.toggle('show',!online);const stateEl=document.getElementById('onlineState');stateEl.querySelector('span:last-child').textContent=online?'Bağlı':'Çevrimdışı';stateEl.style.background=online?'#e8f4ed':'#fff0ef';stateEl.style.color=online?'var(--ok)':'var(--danger)';stateEl.querySelector('.dot').style.background=online?'#74d69a':'#e27d84'}function formatPhoneInput(e){let d=e.target.value.replace(/\D/g,'');if(d.startsWith('90')&&d.length>=12)d='0'+d.slice(2);d=d.slice(0,11);if(d.length&&d[0]!=='0')d=('0'+d).slice(0,11);let out=d;if(d.length>4)out=d.slice(0,4)+' '+d.slice(4,7)+(d.length>7?' '+d.slice(7,9):'')+(d.length>9?' '+d.slice(9,11):'');e.target.value=out}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{setTab(b.dataset.tab);closePanelMenu()});document.getElementById('panelMenuBtn').onclick=e=>{e.stopPropagation();togglePanelMenu()};document.getElementById('panelMenu').onclick=e=>e.stopPropagation();document.addEventListener('click',closePanelMenu);document.getElementById('dashboardBtn').onclick=()=>{setTab('dashboard');closePanelMenu();window.scrollTo({top:0,behavior:'smooth'})};document.getElementById('refreshBtn').onclick=()=>{closePanelMenu();load()};document.getElementById('installAppBtn').onclick=installApp;document.getElementById('logoutBtn').onclick=logout;document.getElementById('modalClose').onclick=closeModal;document.getElementById('modalCloseBottom').onclick=closeModal;document.getElementById('reservationModal').addEventListener('click',e=>{if(e.target.id==='reservationModal')closeModal()});document.getElementById('reservationForm').onsubmit=saveReservation;document.getElementById('cancelReservationBtn').onclick=cancelReservation;document.getElementById('fCustomerName').addEventListener('change',syncReservationCustomerPhone);document.getElementById('newCustomerFromReservation').onclick=()=>openCustomerModal('reservation');document.getElementById('fPhone').addEventListener('input',formatPhoneInput);document.getElementById('financeModalClose').onclick=closeFinanceModal;document.getElementById('financeCancel').onclick=closeFinanceModal;document.getElementById('financeForm').onsubmit=saveFinanceOperation;document.getElementById('financeDescription').oninput=e=>document.getElementById('descriptionCount').textContent=e.target.value.length;document.getElementById('financeModal').addEventListener('click',e=>{if(e.target.id==='financeModal')closeFinanceModal()});document.getElementById('customerModalClose').onclick=closeCustomerModal;document.getElementById('customerCancel').onclick=closeCustomerModal;document.getElementById('customerForm').onsubmit=saveCustomer;document.getElementById('customerPhone').addEventListener('input',formatPhoneInput);document.getElementById('customerSecondPhone').addEventListener('input',formatPhoneInput);document.getElementById('customerModal').addEventListener('click',e=>{if(e.target.id==='customerModal')closeCustomerModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.getElementById('customerModal').classList.contains('show'))closeCustomerModal();else if(document.getElementById('financeModal').classList.contains('show'))closeFinanceModal();else if(document.getElementById('reservationModal').classList.contains('show'))closeModal()}if(e.ctrlKey&&e.key==='Enter'&&document.getElementById('financeModal').classList.contains('show'))document.getElementById('financeForm').requestSubmit()});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e});window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;showToast('NSX Salon telefona kuruldu.');if(state.tab==='dashboard')renderDashboard()});window.addEventListener('online',updateConnection);window.addEventListener('offline',updateConnection);if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/salontakip/sw.js',{scope:'/salontakip/'}).catch(()=>{}));updateConnection();load();setInterval(()=>{if(!document.hidden&&!state.loading&&!document.querySelector('.modalWrap.show'))load(false)},10000);
</script>
